(6113944, 901151, 103150, '<td valign="top">I would like to see it with the plant a little more to the right and without the specks in the white space</td>', 'I would like to see it with the plant a little more to the right and without the specks in the white space', '2010-08-02 17:06:19.000000', NULL, 1),
(6113947, 900805, 103150, '<td valign="top">harsher blacks might help this a little</td>', 'harsher blacks might help this a little', '2010-08-02 17:09:45.000000', NULL, 1),
(6113969, 901157, 48268, '<td valign="top">I''m not usually a big fan of flower pictures in challenges (over done), but this is just lovely.</td>', 'I''m not usually a big fan of flower pictures in challenges (over done), but this is just lovely.', '2010-08-02 17:19:40.000000', NULL, 1),
(6114078, 901145, 96751, '<td valign="top">Lovely object.  Can;t decide if this would work better (or not) without the reflection.</td>', 'Lovely object.  Can;t decide if this would work better (or not) without the reflection.', '2010-08-02 18:44:02.000000', NULL, 1),
(6114079, 901007, 96751, '<td valign="top">Marvelous portrait, although his pose seems a bit forced.  The lighting is just magnificent.  But I''m not sure this is "minimalist"...</td>', 'Marvelous portrait, although his pose seems a bit forced.  The lighting is just magnificent.  But I''m not sure this is "minimalist"...', '2010-08-02 18:44:05.000000', NULL, 1),
(6114080, 900460, 96751, '<td valign="top">Very clever, and the processing on the hand is absolutely incredible.  But for me, that level of detail keeps it from being "minimalist".</td>', 'Very clever, and the processing on the hand is absolutely incredible.  But for me, that level of detail keeps it from being "minimalist".', '2010-08-02 18:44:59.000000', NULL, 1),
(6114082, 900690, 96751, '<td valign="top">She looks so sad :-(</td>', 'She looks so sad :-(', '2010-08-02 18:45:18.000000', NULL, 1),
(6114083, 900693, 96751, '<td valign="top">Beautiful.  Excellent example of minimalism.  Nicely done.</td>', 'Beautiful.  Excellent example of minimalism.  Nicely done.', '2010-08-02 18:45:47.000000', NULL, 1),
(6114085, 901193, 61084, '<td valign="top">This is low-key...not minimalism.</td>', 'This is low-key...not minimalism.', '2010-08-02 18:46:18.000000', NULL, 1),
(6114088, 901205, 96751, '<td valign="top">Love it.  There is a definite sense of motion and journey, implied in his wake.</td>', 'Love it.  There is a definite sense of motion and journey, implied in his wake.', '2010-08-02 18:46:24.000000', NULL, 1),
(6114089, 901104, 96751, '<td valign="top">Very graceful lines.</td>', 'Very graceful lines.', '2010-08-02 18:46:48.000000', NULL, 1),
(6114090, 901043, 96751, '<td valign="top">I really like the minimal color here,and the story with just the snippets of objects.  Nicely done.</td>', 'I really like the minimal color here,and the story with just the snippets of objects.  Nicely done.', '2010-08-02 18:47:31.000000', NULL, 1),
(6114091, 901044, 96751, '<td valign="top">Flippin'' brilliant!  Could be used for stationary or a greeting card.</td>', 'Flippin'' brilliant!  Could be used for stationary or a greeting card.', '2010-08-02 18:48:09.000000', NULL, 1),
(6114093, 901074, 96751, '<td valign="top">This is a close call for me.  The elements are all right for a minimalist image, but I think the visible portions need to be just a teeny bit darker because it''s rather hard to see.</td>', 'This is a close call for me.  The elements are all right for a minimalist image, but I think the visible portions need to be just a teeny bit darker because it''s rather hard to see.', '2010-08-02 18:48:21.000000', NULL, 1),
(6114094, 900617, 96751, '<td valign="top">My favorite game, but I''m having a hard time seeing this as Minimalist.</td>', 'My favorite game, but I''m having a hard time seeing this as Minimalist.', '2010-08-02 18:48:42.000000', NULL, 1),
(6114095, 900113, 96751, '<td valign="top">Such strange creatures.  Beautifully shot and processed.  Love the antenae.</td>', 'Such strange creatures.  Beautifully shot and processed.  Love the antenae.', '2010-08-02 18:49:05.000000', NULL, 1),
(6114097, 901211, 96751, '<td valign="top">Wonderful idea, although the lighting on the starfish seems a bit murky to me.</td>', 'Wonderful idea, although the lighting on the starfish seems a bit murky to me.', '2010-08-02 18:49:30.000000', NULL, 1),
(6114100, 900911, 96751, '<td valign="top">Nice simplicity, I like the softness of this image.</td>', 'Nice simplicity, I like the softness of this image.', '2010-08-02 18:50:23.000000', NULL, 1),
(6114102, 901138, 96751, '<td valign="top">Love the perspective and tilt shift effect.  Excellent street scene image, but not minimalist to me.</td>', 'Love the perspective and tilt shift effect.  Excellent street scene image, but not minimalist to me.', '2010-08-02 18:51:14.000000', NULL, 1),
(6114103, 901164, 96751, '<td valign="top">Great preservation of detail.</td>', 'Great preservation of detail.', '2010-08-02 18:51:17.000000', NULL, 1),
(6114104, 901089, 96751, '<td valign="top">Almost looks edible.  I want to reach out and touch it.</td>', 'Almost looks edible.  I want to reach out and touch it.', '2010-08-02 18:51:40.000000', NULL, 1),
(6114106, 900444, 96751, '<td valign="top">A very sculptural image.  Intriguing motion blur, great lines and lighting.</td>', 'A very sculptural image.  Intriguing motion blur, great lines and lighting.', '2010-08-02 18:52:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6114107, 901126, 96751, '<td valign="top">Wonderful.  Truly minimal!!!</td>', 'Wonderful.  Truly minimal!!!', '2010-08-02 18:52:36.000000', NULL, 1),
(6114112, 901071, 96751, '<td valign="top">Love what you''ve done with the shoes!</td>', 'Love what you''ve done with the shoes!', '2010-08-02 18:53:00.000000', NULL, 1),
(6114114, 900647, 96751, '<td valign="top">This is so good it hurts.  Don''t know what all those little specks are on the ground, but it sure gets my imagination going.  And the sharpness but delicacy of the fishing poles.  It''s just breathtaking.  My favorite of the challenge.  I am humbled by your greatness :-)</td>', 'This is so good it hurts.  Don''t know what all those little specks are on the ground, but it sure gets my imagination going.  And the sharpness but delicacy of the fishing poles.  It''s just breathtaking.  My favorite of the challenge.  I am humbled by your greatness :-)', '2010-08-02 18:54:18.000000', NULL, 1),
(6114115, 901024, 96751, '<td valign="top">Oh, this is so wonderful!!!  I love fog shots.  I just wish that large rock under his right oar wasn''t there.</td>', 'Oh, this is so wonderful!!!  I love fog shots.  I just wish that large rock under his right oar wasn''t there.', '2010-08-02 18:54:21.000000', NULL, 1),
(6114116, 900609, 96751, '<td valign="top">Perfect, Zen-like.</td>', 'Perfect, Zen-like.', '2010-08-02 18:54:39.000000', NULL, 1),
(6114117, 901119, 96751, '<td valign="top">The textures are just wonderful in this macro.  And I like the metallic quality, but it''s not really Minimalist.</td>', 'The textures are just wonderful in this macro.  And I like the metallic quality, but it''s not really Minimalist.', '2010-08-02 18:55:08.000000', NULL, 1),
(6114118, 901193, 96751, '<td valign="top">This is a masterful example of lighting.  Just exquisite.</td>', 'This is a masterful example of lighting.  Just exquisite.', '2010-08-02 18:55:32.000000', NULL, 1),
(6114119, 900672, 96751, '<td valign="top">This has a lovely, dreamlike quality.</td>', 'This has a lovely, dreamlike quality.', '2010-08-02 18:56:10.000000', NULL, 1),
(6114120, 900881, 96751, '<td valign="top">Great dof shot.  Love the contrast of the black o with the subtlety of the rest of the shot.</td>', 'Great dof shot.  Love the contrast of the black o with the subtlety of the rest of the shot.', '2010-08-02 18:56:42.000000', NULL, 1),
(6114121, 900868, 96751, '<td valign="top">This is so Ingmar Bergman!!!  I can actually hear him should "Action!".  This is wonderful in so many ways.</td>', 'This is so Ingmar Bergman!!!  I can actually hear him should "Action!".  This is wonderful in so many ways.', '2010-08-02 18:57:31.000000', NULL, 1),
(6114122, 901097, 96751, '<td valign="top">There is something very spiritual about this image.  Beautiful.</td>', 'There is something very spiritual about this image.  Beautiful.', '2010-08-02 18:57:55.000000', NULL, 1),
(6114123, 900142, 96751, '<td valign="top">Terrific lighting on this.</td>', 'Terrific lighting on this.', '2010-08-02 18:58:11.000000', NULL, 1),
