(6121241, 900868, 117314, '<td valign="top">This is  beautiful minimal shot. I like the way you kept the b/g and still manage to keep it minimal.</td>', 'This is  beautiful minimal shot. I like the way you kept the b/g and still manage to keep it minimal.', '2010-08-06 23:21:41.000000', NULL, 1),
(6121246, 900742, 117314, '<td valign="top">Beautiful shot. This one is much better than a few other similar (birds) entries in the challenge.</td>', 'Beautiful shot. This one is much better than a few other similar (birds) entries in the challenge.', '2010-08-06 23:25:55.000000', NULL, 1),
(6121381, 901126, 75618, '<td valign="top">I would have cropped a few pixels from the bottom but this is breath...taking lol. This is what the challenge is about for me - minimalist yet substantial. You get my personal blue. 9</td>', 'I would have cropped a few pixels from the bottom but this is breath...taking lol. This is what the challenge is about for me - minimalist yet substantial. You get my personal blue. 9', '2010-08-07 03:06:13.000000', NULL, 1),
(6121382, 901091, 75618, '<td valign="top">Elegantly executed. The lighting is spot-on. 8</td>', 'Elegantly executed. The lighting is spot-on. 8', '2010-08-07 03:08:09.000000', NULL, 1),
(6121383, 900742, 23484, '<td valign="top">I really like the angle. Nice contrast.</td>', 'I really like the angle. Nice contrast.', '2010-08-07 03:08:53.000000', NULL, 1),
(6121384, 901187, 23484, '<td valign="top">I love the processing to give it that overblown look. Nice.</td>', 'I love the processing to give it that overblown look. Nice.', '2010-08-07 03:09:51.000000', NULL, 1),
(6121386, 901102, 23484, '<td valign="top">Excellent composition and great contrast.</td>', 'Excellent composition and great contrast.', '2010-08-07 03:10:23.000000', NULL, 1),
(6121388, 900444, 23484, '<td valign="top">Very abstract and very neat.</td>', 'Very abstract and very neat.', '2010-08-07 03:10:42.000000', NULL, 1),
(6121389, 901075, 23484, '<td valign="top">Very neat layered look.</td>', 'Very neat layered look.', '2010-08-07 03:10:58.000000', NULL, 1),
(6121390, 900768, 75618, '<td valign="top">Delicate, haunting... the high contrast and unusual composition work. 9</td>', 'Delicate, haunting... the high contrast and unusual composition work. 9', '2010-08-07 03:14:30.000000', NULL, 1),
(6121391, 900609, 75618, '<td valign="top">Love the composition and the serenity... A couple nitpicks though - blotches in the water (from cloning?). I usually love borders but the heavy black detracts from the stillness of the image. 7</td>', 'Love the composition and the serenity... A couple nitpicks though - blotches in the water (from cloning?). I usually love borders but the heavy black detracts from the stillness of the image. 7', '2010-08-07 03:19:08.000000', NULL, 1),
(6121393, 901007, 75618, '<td valign="top">Excellent work, minimalism is not only conveyed through the composition but also in the concept of the image. 8</td>', 'Excellent work, minimalism is not only conveyed through the composition but also in the concept of the image. 8', '2010-08-07 03:26:02.000000', NULL, 1),
(6121395, 900542, 75618, '<td valign="top">Are those papaya leaves? This is gorgeous, a seemingly ordinary object captured and presented brilliantly. Perfect title, exactly what comes to mind with the way the leaves rot and curl delicately. 9</td>', 'Are those papaya leaves? This is gorgeous, a seemingly ordinary object captured and presented brilliantly. Perfect title, exactly what comes to mind with the way the leaves rot and curl delicately. 9', '2010-08-07 03:38:59.000000', NULL, 1),
(6121397, 901138, 75618, '<td valign="top">It doesn''t really typify minimalism for me but I like the image. Great vantage point and "miniaturization."  7</td>', 'It doesn''t really typify minimalism for me but I like the image. Great vantage point and "miniaturization."  7', '2010-08-07 03:41:23.000000', NULL, 1),
(6121405, 901139, 75618, '<td valign="top">Gorgeously creepy. =P Love the backlighting and the overall feel of the image. I feel like the composition is a bit off though. The slight angle is distracting. I would have preferred more negative space or a completely centered one with the subject facing straight ahead. 6</td>', 'Gorgeously creepy. =P Love the backlighting and the overall feel of the image. I feel like the composition is a bit off though. The slight angle is distracting. I would have preferred more negative space or a completely centered one with the subject facing straight ahead. 6', '2010-08-07 03:48:26.000000', NULL, 1),
(6121406, 901118, 99506, '<td valign="top">Nice shot but there seems to be a good deal of residue left showing distinct crop marks</td>', 'Nice shot but there seems to be a good deal of residue left showing distinct crop marks', '2010-08-07 03:49:01.000000', NULL, 1),
(6121409, 899744, 75618, '<td valign="top">Not a fan of the "flat grays" but this is very magical. 7</td>', 'Not a fan of the "flat grays" but this is very magical. 7', '2010-08-07 03:51:31.000000', NULL, 1),
(6121415, 901195, 75618, '<td valign="top">The bold geometrical shapes make this an interesting semi-abstract. I''m deducting a point because there are so many dust bunnies everywhere , clean your sensor. =P 6</td>', 'The bold geometrical shapes make this an interesting semi-abstract. I''m deducting a point because there are so many dust bunnies everywhere , clean your sensor. =P 6', '2010-08-07 03:55:39.000000', NULL, 1),
(6121420, 901134, 75618, '<td valign="top">It''s a good image but it doesn''t really convey minimalism to me. There are too many things that are vying for my attention. 6</td>', 'It''s a good image but it doesn''t really convey minimalism to me. There are too many things that are vying for my attention. 6', '2010-08-07 04:03:20.000000', NULL, 1),
