(6123147, 900868, 66384, '<td valign="top">Love the composition and title. I think it would be more effective with more contrast. This seems a bit too gray. 7</td>', 'Love the composition and title. I think it would be more effective with more contrast. This seems a bit too gray. 7', '2010-08-08 15:27:37.000000', NULL, 1),
(6123152, 900881, 66384, '<td valign="top">Nice design and good idea. I''d clean up the lens dirt spots if it were mine. The one in the center is particularly distracting.</td>', 'Nice design and good idea. I''d clean up the lens dirt spots if it were mine. The one in the center is particularly distracting.', '2010-08-08 15:30:57.000000', NULL, 1),
(6123158, 900853, 66384, '<td valign="top">The black in the lower right corner is distracting to me. I don''t know what it is or why it''s there. The lack of any other spots on the dice is very effective.</td>', 'The black in the lower right corner is distracting to me. I don''t know what it is or why it''s there. The lack of any other spots on the dice is very effective.', '2010-08-08 15:36:58.000000', NULL, 1),
(6123161, 900344, 66384, '<td valign="top">Beautiful portrait.</td>', 'Beautiful portrait.', '2010-08-08 15:37:36.000000', NULL, 1),
(6123163, 900945, 66384, '<td valign="top">I''d like it better without the three black spots.</td>', 'I''d like it better without the three black spots.', '2010-08-08 15:38:57.000000', NULL, 1),
(6123167, 900213, 66384, '<td valign="top">Very nice image. Title could be a bit more minimal ;) (doesn''t effect my rating)</td>', 'Very nice image. Title could be a bit more minimal ;) (doesn''t effect my rating)', '2010-08-08 15:48:42.000000', NULL, 1),
(6123171, 901150, 66384, '<td valign="top">The spots from the dirty lens are very distracting. Clean those up and you''d have an excellent image.</td>', 'The spots from the dirty lens are very distracting. Clean those up and you''d have an excellent image.', '2010-08-08 15:51:19.000000', NULL, 1),
(6123180, 900779, 66384, '<td valign="top">I wish the image was sharper. I like your idea and composition. The crop seems a little too tight on the bottom.</td>', 'I wish the image was sharper. I like your idea and composition. The crop seems a little too tight on the bottom.', '2010-08-08 15:55:10.000000', NULL, 1),
(6123181, 901054, 66384, '<td valign="top">Very cool.</td>', 'Very cool.', '2010-08-08 15:56:23.000000', NULL, 1),
(6123183, 901024, 1030, '<td valign="top">Good composition, very well done!!!  9!!</td>', 'Good composition, very well done!!!  9!!', '2010-08-08 15:59:34.000000', NULL, 1),
(6123184, 901223, 66384, '<td valign="top">Well, there is black and bluish white. The definition didn''t say anything specific about the meaning of black and white, so I guess you met the challenge in a very out of the box way. Nice going.</td>', 'Well, there is black and bluish white. The definition didn''t say anything specific about the meaning of black and white, so I guess you met the challenge in a very out of the box way. Nice going.', '2010-08-08 15:59:47.000000', NULL, 1),
