(6123205, 901101, 76335, '<td valign="top">Minimal indeed. The bird could be sharper, the sky a tad brighter. Would be nice to see a head -- or at least a beak!</td>', 'Minimal indeed. The bird could be sharper, the sky a tad brighter. Would be nice to see a head -- or at least a beak!', '2010-08-08 16:07:50.000000', NULL, 1),
(6123206, 901231, 76335, '<td valign="top">Nice. I love the pattern up above.</td>', 'Nice. I love the pattern up above.', '2010-08-08 16:10:11.000000', NULL, 1),
(6123216, 901068, 73142, '<td valign="top">Really nice! Wish the building wasn''t leaning to the right...</td>', 'Really nice! Wish the building wasn''t leaning to the right...', '2010-08-08 16:18:48.000000', NULL, 1),
(6123221, 900553, 73142, '<td valign="top">Nice photo! The lord is alone? Don''t get it...</td>', 'Nice photo! The lord is alone? Don''t get it...', '2010-08-08 16:20:41.000000', NULL, 1),
(6123282, 900990, 23484, '<td valign="top">I like the nice dark colors.</td>', 'I like the nice dark colors.', '2010-08-08 17:18:47.000000', NULL, 1),
(6123283, 901136, 23484, '<td valign="top">Very nicely done. Good job on the contrast.</td>', 'Very nicely done. Good job on the contrast.', '2010-08-08 17:19:20.000000', NULL, 1),
