(6123297, 901106, 76335, '<td valign="top">A simple and pleasing composition, but not really "minimalism" as I think of it.</td>', 'A simple and pleasing composition, but not really "minimalism" as I think of it.', '2010-08-08 17:43:46.000000', NULL, 1),
(6123298, 900113, 76335, '<td valign="top">I love the backwards glance.</td>', 'I love the backwards glance.', '2010-08-08 17:44:06.000000', NULL, 1),
(6123301, 901188, 76335, '<td valign="top">An interesting and intriguingly composed still life. Minimalism? Maybe. I''m not sure...</td>', 'An interesting and intriguingly composed still life. Minimalism? Maybe. I''m not sure...', '2010-08-08 17:45:04.000000', NULL, 1),
(6123304, 901038, 76335, '<td valign="top">Great idea. I want to like this more than I do, but I''m not crazy about the processing -- the halos around the objects.</td>', 'Great idea. I want to like this more than I do, but I''m not crazy about the processing -- the halos around the objects.', '2010-08-08 17:46:34.000000', NULL, 1),
(6123328, 901231, 100831, '<td valign="top">nice concept.</td>', 'nice concept.', '2010-08-08 18:07:00.000000', NULL, 1),
(6123390, 900612, 23484, '<td valign="top">Very cool dark shot. Nice angles.</td>', 'Very cool dark shot. Nice angles.', '2010-08-08 18:55:21.000000', NULL, 1),
(6123491, 900339, 76185, '<td valign="top">Fantastic image, nails the minimalism with an appearing narrative.</td>', 'Fantastic image, nails the minimalism with an appearing narrative.', '2010-08-08 19:37:41.000000', NULL, 1),
(6123492, 901076, 76185, '<td valign="top">Elegant and simple - beautiful.</td>', 'Elegant and simple - beautiful.', '2010-08-08 19:38:18.000000', NULL, 1),
(6123493, 900473, 76185, '<td valign="top">The blur of the clouds really enhances the otherworldliness of this. Great stuff.</td>', 'The blur of the clouds really enhances the otherworldliness of this. Great stuff.', '2010-08-08 19:39:08.000000', NULL, 1),
(6123495, 901193, 76185, '<td valign="top">Very effective lighting, excellent work.</td>', 'Very effective lighting, excellent work.', '2010-08-08 19:40:52.000000', NULL, 1),
(6123498, 900641, 76335, '<td valign="top">Interesting, but not really minimalism.</td>', 'Interesting, but not really minimalism.', '2010-08-08 19:45:40.000000', NULL, 1),
(6123501, 900542, 76335, '<td valign="top">Call and response. This is beautiful.</td>', 'Call and response. This is beautiful.', '2010-08-08 19:46:30.000000', NULL, 1),
(6123502, 900265, 76335, '<td valign="top">Points for presenting a sunrise in black and white.</td>', 'Points for presenting a sunrise in black and white.', '2010-08-08 19:47:11.000000', NULL, 1),
(6123520, 900805, 76335, '<td valign="top">I do like the mid-key rendering of this.</td>', 'I do like the mid-key rendering of this.', '2010-08-08 20:02:00.000000', NULL, 1),
(6123523, 901041, 76335, '<td valign="top">That''s quite a chair, and the negative space does it justice. What could it possibly share the frame with?</td>', 'That''s quite a chair, and the negative space does it justice. What could it possibly share the frame with?', '2010-08-08 20:03:06.000000', NULL, 1),
(6123525, 901066, 76335, '<td valign="top">Fabulous shapes and forms (er, lines and shapes). A bit too sharp, I think, but a great composition in any case.</td>', 'Fabulous shapes and forms (er, lines and shapes). A bit too sharp, I think, but a great composition in any case.', '2010-08-08 20:03:48.000000', NULL, 1),
(6123529, 901068, 76335, '<td valign="top">Much too busy to be called minimalism. But the church against that sky makes for a powerful image (challenge themes aside).</td>', 'Much too busy to be called minimalism. But the church against that sky makes for a powerful image (challenge themes aside).', '2010-08-08 20:06:06.000000', NULL, 1),
(6123534, 901232, 76335, '<td valign="top">Much too busy to be called minimalism. Not that it''s not an impressive black and white landscape...</td>', 'Much too busy to be called minimalism. Not that it''s not an impressive black and white landscape...', '2010-08-08 20:07:44.000000', NULL, 1),
(6123544, 900742, 76335, '<td valign="top">I love the progression.</td>', 'I love the progression.', '2010-08-08 20:12:20.000000', NULL, 1),
(6123545, 901098, 76335, '<td valign="top">Dreamy...</td>', 'Dreamy...', '2010-08-08 20:12:34.000000', NULL, 1),
(6123548, 900530, 76335, '<td valign="top">A beautiful image. Can''t call it minimalism though.</td>', 'A beautiful image. Can''t call it minimalism though.', '2010-08-08 20:13:43.000000', NULL, 1),
(6123556, 900142, 76335, '<td valign="top">Fractalicious.</td>', 'Fractalicious.', '2010-08-08 20:18:26.000000', NULL, 1),
(6123677, 901124, 100831, '<td valign="top">I like the mystery. Nice stripes</td>', 'I like the mystery. Nice stripes', '2010-08-08 21:10:18.000000', NULL, 1),
(6123695, 901212, 76335, '<td valign="top">I feel like I''m literally being pulled into this. Wild. Good.</td>', 'I feel like I''m literally being pulled into this. Wild. Good.', '2010-08-08 21:31:31.000000', NULL, 1),
(6123699, 901104, 76335, '<td valign="top">Incredible. The composition is what really strikes me. The "stroke" seems to end just outside the right side of the frame. Or does it? <br/> <br/>I like that the image is soft and the contrast subdued. Adds to the mystery.</td>', 'Incredible. The composition is what really strikes me. The "stroke" seems to end just outside the right side of the frame. Or does it?  I like that the image is soft and the contrast subdued. Adds to the mystery.', '2010-08-08 21:32:23.000000', NULL, 1),
(6123700, 900609, 76335, '<td valign="top">A beautifully understated still life.</td>', 'A beautifully understated still life.', '2010-08-08 21:32:37.000000', NULL, 1),
(6123701, 900969, 76335, '<td valign="top">So elusive.</td>', 'So elusive.', '2010-08-08 21:32:40.000000', NULL, 1);
