(6123703, 901234, 76335, '<td valign="top">Now that''s minimal. Excellent.</td>', 'Now that''s minimal. Excellent.', '2010-08-08 21:32:52.000000', NULL, 1),
(6123713, 900589, 76335, '<td valign="top">01000010 01110010 01101001 01101100 01101100 01101001 01100001 01101110 01110100 00101110</td>', '01000010 01110010 01101001 01101100 01101100 01101001 01100001 01101110 01110100 00101110', '2010-08-08 21:35:05.000000', NULL, 1),
(6123714, 901024, 76335, '<td valign="top">Full of atmosphere. Great job.</td>', 'Full of atmosphere. Great job.', '2010-08-08 21:35:08.000000', NULL, 1),
(6123727, 900817, 76335, '<td valign="top">Amazing those textures, enhanced nicely by the soft background bokeh. Beautiful.</td>', 'Amazing those textures, enhanced nicely by the soft background bokeh. Beautiful.', '2010-08-08 21:39:20.000000', NULL, 1),
(6123729, 901044, 76335, '<td valign="top">The open beak makes the shot for me...</td>', 'The open beak makes the shot for me...', '2010-08-08 21:40:55.000000', NULL, 1),
