(6123733, 900779, 76335, '<td valign="top">I''m torn between wishing there were more clearance between the line and the frame, and... well, leaving it like it is. In any case, it''s one of the more thought-provoking of the birds-on-a-wire shots.</td>', 'I''m torn between wishing there were more clearance between the line and the frame, and... well, leaving it like it is. In any case, it''s one of the more thought-provoking of the birds-on-a-wire shots.', '2010-08-08 21:42:57.000000', NULL, 1),
(6123739, 900819, 76335, '<td valign="top">The devil''s rhythm?</td>', 'The devil''s rhythm?', '2010-08-08 21:45:08.000000', NULL, 1),
(6123740, 900868, 76335, '<td valign="top">Strong composition.</td>', 'Strong composition.', '2010-08-08 21:45:37.000000', NULL, 1),
(6123741, 901120, 76335, '<td valign="top">The repeating pattern is oppressive in its monotony. Minimal in a different way. I like it.</td>', 'The repeating pattern is oppressive in its monotony. Minimal in a different way. I like it.', '2010-08-08 21:46:15.000000', NULL, 1),
(6123742, 901121, 76335, '<td valign="top">I see this scoring high. Excellent.</td>', 'I see this scoring high. Excellent.', '2010-08-08 21:46:17.000000', NULL, 1),
(6123743, 901043, 76335, '<td valign="top">Expert composition.</td>', 'Expert composition.', '2010-08-08 21:47:12.000000', NULL, 1),
(6123744, 901126, 76335, '<td valign="top">So much impact for so little content. A winner by me.</td>', 'So much impact for so little content. A winner by me.', '2010-08-08 21:47:13.000000', NULL, 1),
