(6123759, 899763, 76335, '<td valign="top">I''m deciding that I like this. The shallow DOF and the flower''s placement in the frame make it feel very tangible -- like I can reach out and touch it (or like it''s going to reach out and touch me). Quite good.</td>', 'I''m deciding that I like this. The shallow DOF and the flower''s placement in the frame make it feel very tangible -- like I can reach out and touch it (or like it''s going to reach out and touch me). Quite good.', '2010-08-08 21:49:05.000000', NULL, 1),
(6123760, 900647, 76335, '<td valign="top">I have a feeling this is taking a beating on its score. But I''m completely intrigued by it.</td>', 'I have a feeling this is taking a beating on its score. But I''m completely intrigued by it.', '2010-08-08 21:49:08.000000', NULL, 1),
(6123762, 900344, 76335, '<td valign="top">Low key minimalism. Love the light.</td>', 'Low key minimalism. Love the light.', '2010-08-08 21:49:13.000000', NULL, 1),
(6123763, 901235, 76335, '<td valign="top">More candy for the imagination from... cutout?</td>', 'More candy for the imagination from... cutout?', '2010-08-08 21:49:14.000000', NULL, 1),
